import { createServer } from "node:http";
import * as client from "@prometheus-io/client";

const registry = new client.Registry();

const tokens = new client.Counter({
  name: "ai_agents_llm_tokens_total",
  help: "Tokens through the gateway",
  labelNames: ["agent", "step", "type"],
  registers: [registry],
});

const costUsd = new client.Counter({
  name: "ai_agents_llm_cost_usd_total",
  help: "Estimated cost in USD",
  labelNames: ["agent", "step"],
  registers: [registry],
});

const callSeconds = new client.Histogram({
  name: "ai_agents_llm_call_seconds",
  help: "Wall time of one model call",
  labelNames: ["agent"],
  buckets: [1, 5, 15, 30, 60],
  registers: [registry],
});

// a pretend model call every second: Nova in the build step, and one call in ten is slow
const durations = [0.8, 1.6, 2.4, 0.9, 3.1, 1.2, 2.2, 0.7, 1.9, 24];
let n = 0;
setInterval(() => {
  const seconds = durations[n++ % durations.length];
  tokens.inc({ agent: "nova", step: "build", type: "input" }, 1200);
  tokens.inc({ agent: "nova", step: "build", type: "output" }, 300);
  costUsd.inc({ agent: "nova", step: "build" }, (1200 * 4 + 300 * 20) / 1_000_000);
  callSeconds.observe({ agent: "nova" }, seconds);
}, 1000);

createServer(async (req, res) => {
  if (req.url !== "/metrics") return res.writeHead(404).end();
  res.writeHead(200, { "Content-Type": registry.contentType }).end(await registry.metrics());
}).listen(9090, () => console.log("metrics on http://localhost:9090/metrics"));
